before.content:
    Path workspaceRoot,
    String model,
    String baseUrl,
    int port) {
public JiHostProperties {
    dataDirectory = dataDirectory == null ? Path.of(System.getProperty("user.home"), ".ji") : dataDirectory;
    workspaceRoot = workspaceRoot == null ? Path.of(".") : workspaceRoot;

after.content:
        workspaceRoot = workspaceRoot == null ? Path.of(".") : workspaceRoot;
        model = model == null ? "" : model;
        baseUrl = baseUrl == null ? "" : baseUrl;
        if (contextWindowTokens < 0) {
            throw new IllegalArgumentException("ji.host.context-window-tokens is out of range");
        }
        if (port < 0 || port > 65_535) throw new IllegalArgumentException("ji.host.port is out of range");
        if (hcpPort < 0 || hcpPort > 65_535) {
            throw new IllegalArgumentException("ji.host.hcp-port is out of range");
        }
    }
}
